cd /tmp; cat > an.py <<'EOF'
import json
from datetime import datetime, timezone, timedelta
from collections import Counter
pages=json.load(open("pages.json"))
for i in range(1,len(pages)):
    if pages[i][0]!=pages[i-1][-1]: print("overlap mismatch page",i,pages[i-1][-1],pages[i][0])
allr=[r for i,p in enumerate(pages) for r in (p if i==0 else p[1:])]
print(len(allr), Counter(r.get("v") for r in allr), Counter(tuple(sorted(r)) for r in allr))
def norm(r):
    if r["v"]==1:
        t=r["ts"]; dt=datetime.fromisoformat(t.replace("Z","+00:00"))
        if dt.tzinfo is None: dt=dt.replace(tzinfo=timezone.utc)
        return dt, r["kwh"]
    return datetime.fromtimestamp(r["ts"]/1000,timezone.utc), r["wh"]/1000
n=[(norm(r),r) for r in allr]
ts=[x[0][0] for x in n]
c=Counter(ts); print("dups",[(k,v) for k,v in c.items() if v>1][:10])
for i in range(1,len(n)):
    d=ts[i]-ts[i-1]
    if d!=timedelta(hours=1): print("step",d,n[i-1][1],n[i][1])
# version transitions
for i in range(1,len(allr)):
    if allr[i]["v"]!=allr[i-1]["v"]: print("vchange",allr[i-1],allr[i])
vals=[x[0][1] for x in n]
print(min(vals),max(vals))
for (t,k),r in n:
    if k is None or k<0 or k>100: print("odd",r)
json.dump([(t.isoformat(),k) for (t,k),_ in n],open("norm.json","w"))
EOF
python3 an.py

