import json, collections
from datetime import datetime, timezone, timedelta
from zoneinfo import ZoneInfo
pages=json.load(open("pages.json"))
# check overlap
for i in range(1,len(pages)):
    if pages[i] and pages[i-1] and pages[i][0]!=pages[i-1][-1]: print("overlap mismatch page",i,pages[i-1][-1],pages[i][0])
allr=[r for p in pages for r in p]
def norm(r):
    if r["v"]==1:
        t=datetime.fromisoformat(r["ts"]).replace(tzinfo=timezone.utc); e=r["kwh"]
    else:
        t=datetime.fromtimestamp(r["ts"]/1000,timezone.utc); e=r["wh"]/1000 if r["wh"] is not None else None
    return t,e
vs=collections.Counter(r["v"] for r in allr); print(vs)
keys=collections.Counter(tuple(sorted(r)) for r in allr); print(keys)
d={}
dups=0;conf=0
for r in allr:
    t,e=norm(r)
    if t in d:
        dups+=1
        if d[t]!=e: conf+=1; print("conflict",t,d[t],e)
    else: d[t]=e
print("dups",dups,"conf",conf,"unique",len(d))
ts=sorted(d)
print(ts[0],ts[-1])
for a,b in zip(ts,ts[1:]):
    if b-a!=timedelta(hours=1): print("gap",a,b)
# order check
prev=None
for r in allr:
    t,_=norm(r)
    if prev and t<prev: print("out of order",prev,t)
    prev=t
vals=[e for e in d.values()]
print("None",sum(v is None for v in vals),"neg",sum(1 for v in vals if v is not None and v<0))
import statistics
print("max",max(v for v in vals if v is not None))
json.dump({k.isoformat():v for k,v in d.items()},open("d.json","w"))
# version switch
for i in range(1,len(allr)):
    if allr[i]["v"]!=allr[i-1]["v"]: print("vswitch",allr[i-1],allr[i])
EOF
