steps.cmd:
mkdir -p /tmp/work && cd /tmp/work && cat <<'EOF' > fetch.py
import subprocess, json, time
pages=[]; cursor=None; log=[]
while True:
    cmd=["meterctl","readings","--meter","M-1001","--limit","100"]
    if cursor is not None: cmd+=["--cursor",str(cursor)]
    for attempt in range(200):
        p=subprocess.run(cmd,capture_output=True,text=True)
        out=p.stdout.strip()
        try: j=json.loads(out)
        except Exception as e:
            log.append(("badjson",cursor,p.returncode,out[:200],p.stderr[:200])); time.sleep(1); continue
        if p.returncode==3 or (isinstance(j,dict) and j.get("error")):
            log.append(("err",cursor,p.returncode,out[:200])); time.sleep(j.get("retry_after_s",1) if isinstance(j,dict) else 1); continue
        if p.returncode!=0:
            log.append(("rc",cursor,p.returncode,out[:200],p.stderr[:200])); time.sleep(1); continue
        break
    else:
        raise SystemExit("too many retries at cursor %r"%cursor)
    pages.append({"cursor":cursor,"resp":j,"stderr":p.stderr})
    print(cursor, len(j["records"]), j.get("next_cursor"), j.get("has_more"), [k for k in j if k not in("records","next_cursor","has_more")])
    if not j.get("has_more") and j.get("next_cursor") is None: break
    if j.get("has_more") != (j.get("next_cursor") is not None): print("  !! has_more/next_cursor mismatch")
    if j.get("next_cursor") is None: break
    cursor=j["next_cursor"]
json.dump(pages,open("pages.json","w"))
print("log entries:",len(log))
for l in log[:20]: print(l)
EOF
python3 fetch.py

