import json, statistics
from datetime import datetime, timezone, timedelta
from zoneinfo import ZoneInfo
LA=ZoneInfo("America/Los_Angeles")
rows=json.load(open("rows.json"))
R=[]
for i,pi,ts,k,r in rows:
    end=datetime.fromisoformat(ts); start=end-timedelta(hours=1)
    R.append(dict(i=i,end=end,start=start,ls=start.astimezone(LA),kwh=k,raw=r))
# daily totals by local date of hour start
days={}
for x in R: days.setdefault(x["ls"].date(),[]).append(x["kwh"])
for d,v in sorted(days.items()):
    print(d, d.strftime("%a"), "n=%2d"%len(v), "sum=%8.2f min=%7.3f med=%7.3f max=%7.3f"%(sum(v),min(v),statistics.median(v),max(v)))
def show(a,b,label):
    print("---",label)
    for x in R:
        if a<=x["end"]<=b: print(x["i"], x["end"].strftime("%m-%d %H:%MZ"), "local hr start", x["ls"].strftime("%m-%d %H:%M %Z"), "%.3f"%x["kwh"], x["raw"])
U=timezone.utc
show(datetime(2026,11,1,5,tzinfo=U),datetime(2026,11,1,12,tzinfo=U),"DST / month start")
show(datetime(2026,11,9,5,tzinfo=U),datetime(2026,11,9,12,tzinfo=U),"v1->v2 switch")
show(datetime(2026,11,13,13,tzinfo=U),datetime(2026,11,13,23,tzinfo=U),"CT change")
show(datetime(2026,12,1,5,tzinfo=U),datetime(2026,12,1,11,tzinfo=U),"month end")
EOF
