cat <<'EOF' > /app/compute_nov_2026.py
import json, subprocess, time, datetime
from zoneinfo import ZoneInfo

METER='M-1001'
TZ=ZoneInfo('America/Los_Angeles')

start_local = datetime.datetime(2026,11,1,0,0,0,tzinfo=TZ)
end_local = datetime.datetime(2026,12,1,0,0,0,tzinfo=TZ)
start_utc = start_local.astimezone(datetime.timezone.utc)
end_utc = end_local.astimezone(datetime.timezone.utc)

flags=set()

def call(cursor=None, limit=100):
    cmd=['meterctl','readings','--meter',METER,'--limit',str(limit)]
    if cursor is not None:
        cmd += ['--cursor', str(cursor)]
    while True:
        p=subprocess.run(cmd, capture_output=True, text=True)
        if p.returncode==3:
            try:
                obj=json.loads((p.stdout or p.stderr).strip())
                time.sleep(obj.get('retry_after_s',1))
            except Exception:
                time.sleep(1)
            continue
        if p.returncode!=0:
            raise RuntimeError(p.stdout+p.stderr)
        return json.loads(p.stdout)

cursor=None
energy_by_ts={}
duplicate_conflicts=0
while True:
    page=call(cursor)
    for r in page['records']:
        if r.get('v')==1:
            ts=datetime.datetime.fromisoformat(r['ts']).replace(tzinfo=datetime.timezone.utc)
            kwh=float(r['kwh'])
        elif r.get('v')==2:
            ts=datetime.datetime.fromtimestamp(r['ts']/1000, tz=datetime.timezone.utc)
            kwh=float(r['wh'])/1000.0
        else:
            flags.add('unknown_record_version')
            continue
        if ts in energy_by_ts:
            # server repeats last record of previous page; tolerate exact duplicates
            if abs(energy_by_ts[ts]-kwh) > 1e-9:
                duplicate_conflicts += 1
        else:
            energy_by_ts[ts]=kwh
    cursor=page.get('next_cursor')
    if not page.get('has_more'):
        break

if duplicate_conflicts:
    flags.add('duplicate_timestamp_conflicts')

recs=sorted(energy_by_ts.items(), key=lambda x:x[0])
selected=[(ts,kwh) for ts,kwh in recs if ts>start_utc and ts<=end_utc]

expected_hours=int((end_local-start_local).total_seconds()//3600)
if len(selected)!=expected_hours:
    flags.add(f'missing_or_extra_hours_{len(selected)}_expected_{expected_hours}')

for (t1,_),(t2,_) in zip(selected, selected[1:]):
    if (t2-t1)!=datetime.timedelta(hours=1):
        flags.add('time_gaps_or_overlaps')
        break

ans=sum(kwh for _,kwh in selected)
print(json.dumps({"answer": ans, "flags": sorted(flags)}))
EOF
